import numpy as np
A=np.array(inp); O=np.array(out)
shape={(0,0),(0,1),(1,2)}
def transforms(sh):
 arr=[]
 for refl in [False,True]:
  for k in range(4):
   pts=[]
   for r,c in sh:
    x,y=(r,-c) if refl else (r,c)
    for _ in range(k): x,y=y,-x
    pts.append((x,y))
   mr=min(x for x,y in pts); mc=min(y for x,y in pts)
   p=frozenset((x-mr,y-mc) for x,y in pts)
   if p not in arr: arr.append(p)
 return arr
